"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["37237"],{33876(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>o,contentTitle:()=>c,toc:()=>l,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies","title":"Get beneficiary policies (v2)","description":"v2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies","permalink":"/docs/pr-47/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get beneficiary policies (v2)","sidebar_label":"Get beneficiary policies (v2)","sidebar_class_name":"api-method api-method--post","description":"v2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get beneficiary policies","permalink":"/docs/pr-47/docs/nhcx/v1/api/registry/endpoints/registry-participant-get-policies"},"next":{"title":"Link payer product","permalink":"/docs/pr-47/docs/nhcx/v1/api/registry/endpoints/registry-product-link"}}'),a=i(62540),r=i(43023),s=i(52563),p=JSON.parse('{"id":"registry_v2_participant_get_policies","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/v2/participant/get/policies","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Get beneficiary policies (v2)","title":"Get beneficiary policies (v2)","description":"v2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.\\n\\n### Business purpose\\n\\nThis endpoint answers the same question as /participant/get/policies: which payer products is this beneficiary linked to, and therefore which payer or TPA should the hospital address. The OpenAPI document exposes it as getParticipantGetPoliciesV2 with an identical request and response schema and the same Registry APIs tag; the documentation records no behavioural difference beyond the path. Integrations that use the v2 link and de-link calls typically read back through this endpoint.\\n\\n### When to use\\n\\nUse it at the same point as the v1 lookup, before eligibility and pre-authorisation. Payers also use it to check a link they just made.\\n\\n### Preconditions\\n\\n- You have a valid access token in the `bearer_auth` header.\\n- The payer or TPA has already linked the member.\\n- Send the ABHA number without hyphens.\\n\\n### Postconditions\\n\\nYou get the member\'s linked policies. Cache them, and force a refresh when something changes on the payer side.\\n\\n### Common mistakes\\n\\n- Using the payer ID as `x-hcx-recipient_code`. Use the processing ID from this response.\\n- Sending the ABHA number with hyphens.\\n- Trying only one identifier type.\\n\\n### Best practices\\n\\n- Normalise the ABHA number (strip separators) before the call and try identifiers in the documented priority order: ABHA, then MemberId from the latest admission, then mobile number.\\n- Cache successful lookups keyed by patient, but expose a forceRefresh path and use it as the first diagnostic step when a preauth is rejected for a coverage mismatch.\\n- Store payerId, memberId, productId, productName and policyNumber from the result; these feed x-hcx-recipient_code, the Coverage and Patient identifiers and the InsurancePlan lookup.\\n- If the lookup yields nothing, fall back to a coverage-eligibility check with purpose discovery to obtain the active policy code.\\n- Keep the token fresh; retry once on 401.\\n\\n### Related scenario\\n\\nA TPA has just linked a new member through /v2/participant/link/abha/policy and wants to verify the write before closing the ticket. It calls /v2/participant/get/policies with identifiertype AbhaNumber and the member\'s hyphen-free ABHA number and sees the product returned. Months later the same member is admitted; the hospital\'s HMIS runs the identifier cascade (ABHA, then member ID, then mobile) against this endpoint, caches the result, and proceeds to /v1/insuranceplan/request and /v1/preauth/submit addressed to the TPA\'s participant code taken from processingID.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[{"name":"Accept","required":true,"description":"Always `application/json` on the participant service.","example":"application/json","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"identifiertype","type":"string","required":false,"description":"","encrypted":false},{"name":"identifiervalue","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"identifiertype":"MemberId","identifiervalue":"MEM-2026-000123"},"responses":[{"status":"200","description":"Returns HTTP 200 with ParticipantListResponse (optional participantdetails array of participantcode, participantname, address, state).","example":{"participantdetails":[{"participantcode":"100234@sbx","participantname":"Demo Health Insurance Co","address":"Plot 12, Sector 5, Gurugram","state":"Haryana"}]},"synthesised":false,"fields":[{"name":"participantdetails","type":"object[]","required":false,"description":""},{"name":"participantdetails.participantcode","type":"string","required":false,"description":""},{"name":"participantdetails.participantname","type":"string","required":false,"description":""},{"name":"participantdetails.address","type":"string","required":false,"description":""},{"name":"participantdetails.state","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"identifiertype\\": \\"MemberId\\",\\n  \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"identifiertype\\": \\"MemberId\\",\\n  \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Accept\\": \\"application/json\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"identifiertype\\": \\"MemberId\\",\\n        \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Accept\\": \\"application/json\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"identifiertype\\": \\"MemberId\\",\\n    \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Accept\\", \\"application/json\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"identifiertype\\": \\"MemberId\\",\\n            \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Accept: application/json\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"identifiertype\\": \\"MemberId\\",\\n        \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"identifiertype\\": \\"MemberId\\",\\n  \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Accept\\", \\"application/json\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Accept\\", \\"application/json\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"identifiertype\\": \\"MemberId\\",\\n        \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/v2/participant/get/policies\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Accept\'] = \'application/json\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"identifiertype\\": \\"MemberId\\",\\n    \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let o={title:"Get beneficiary policies (v2)",sidebar_label:"Get beneficiary policies (v2)",sidebar_class_name:"api-method api-method--post",description:"v2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,d={},l=[];function h(e){return(0,a.jsx)(s.Ay,{operation:p})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);